      code: 'import { setActivePinia, createPinia } from \'pinia\'\nimport { describe, it, expect, beforeEach } from \'vitest\'\nimport { useExpenseStore } from \'../expenses\'\n\nconst e = (over = {}) => ({ title: \'Tea\', amount: 2000, category: \'Food\', date: \'2026-11-05\', note: \'\', ...over })\n\ndescribe(\'expense store\', () => {\n  beforeEach(() => {\n    localStorage.clear()\n    setActivePinia(createPinia())\n  })\n\n  it(\'adds an expense with an id\', () => {\n    const s = useExpenseStore()\n    const added = s.add(e())\n    expect(added.id).toBeTruthy()\n    expect(s.expenses).toHaveLength(1)\n  })\n\n  it(\'updates and removes\', () => {\n    const s = useExpenseStore()\n    const { id } = s.add(e())\n    s.update(id, { amount: 5000 })\n    expect(s.getById(id).amount).toBe(5000)\n    s.remove(id)\n    expect(s.getById(id)).toBeUndefined()\n  })\n\n  it(\'totals by month and category in paise\', () => {\n    const s = useExpenseStore()\n    s.add(e({ amount: 10 }))                                 // Rs 0.10\n    s.add(e({ amount: 20 }))                                 // Rs 0.20\n    s.add(e({ amount: 99900, category: \'Bills\' }))\n    s.add(e({ amount: 70000, date: \'2026-10-30\' }))          // other month\n    expect(s.totalFor(\'2026-11\')).toBe(99930)                // no 0.30000000000000004!\n    expect(s.byCategory(\'2026-11\')).toEqual({ Food: 30, Bills: 99900 })\n  })\n\n  it(\'persists to localStorage\', async () => {\n    const s = useExpenseStore()\n    s.add(e())\n    await Promise.resolve()   // let the watcher flush\n    expect(JSON.parse(localStorage.getItem(\'et-expenses\'))).toHaveLength(1)\n  })\n})',
      result: 'Vitest prints: expense store (4 tests) passed. Storing paise as integers makes the 0.10 + 0.20 total exact.',
      explanation: 'Each test starts with an empty store and storage, so they are independent. Money is tested in the smallest unit to avoid floating-point surprises; formatting is a view concern.',
