      task: 'Practical test 5: Add a getter "monthlyTrend" that returns the last 6 months with totals, and render it as bars on the dashboard.',
      hint: 'Generate month keys with Date, reuse totalFor.',
      solution: '// in the expenses setup store\nconst monthlyTrend = computed(() => {\n  const now = new Date()\n  return Array.from({ length: 6 }, (_, i) => {\n    const d = new Date(now.getFullYear(), now.getMonth() - (5 - i), 1)\n    const key = d.getFullYear() + \'-\' + String(d.getMonth() + 1).padStart(2, \'0\')\n    return { month: key, label: d.toLocaleString(\'en-IN\', { month: \'short\' }), total: totalFor(key) }\n  })\n})\n// return { ..., monthlyTrend }\n\n<!-- DashboardView.vue -->\n<script setup>\nimport { computed } from \'vue\'\nconst store = useExpenseStore()\nconst max = computed(() => Math.max(1, ...store.monthlyTrend.map(m => m.total)))\n</script>\n<template>\n  <div class="trend">\n    <div v-for="m in store.monthlyTrend" :key="m.month" class="col">\n      <div class="bar" :style="{ height: (m.total / max * 100) + \'%\' }" :title="m.total / 100"></div>\n      <small>{{ m.label }}</small>\n    </div>\n  </div>\n</template>\n<style scoped>\n.trend { display: flex; gap: 8px; height: 120px; align-items: flex-end }\n.col { flex: 1; display: flex; flex-direction: column; justify-content: flex-end; height: 100% }\n.bar { background: #42b883; border-radius: 4px 4px 0 0; transition: height .4s }\n</style>',
